void DriveFsQuotaDelegateAsyncWaiter::GetDriveFsFreeSpaceBytes(
    int64_t* out_free_remaining_bytes) {
  base::RunLoop loop;
  proxy_->GetDriveFsFreeSpaceBytes(
      base::BindOnce(
          [](base::RunLoop* loop,
             int64_t* out_free_remaining_bytes
,
             int64_t free_remaining_bytes) {*out_free_remaining_bytes = std::move(free_remaining_bytes);
            loop->Quit();
          },
          &loop,
          out_free_remaining_bytes));
  loop.Run();
}

int64_t DriveFsQuotaDelegateAsyncWaiter::GetDriveFsFreeSpaceBytes(
    ) {
  int64_t async_wait_result;
  GetDriveFsFreeSpaceBytes(&async_wait_result);
  return async_wait_result;
}




